package defaulting

import (
	"github.com/Dynatrace/dynatrace-operator/pkg/api/latest/dynakube"
	ctrl "sigs.k8s.io/controller-runtime"
)

// SetupWebhookWithManager registers the defaulting webhooks.
//
// The defaulting webhooks are served on the paths generated by controller-runtime.
// - DynaKube: /mutate-dynatrace-com-v1beta6-dynakube.
func SetupWebhookWithManager(mgr ctrl.Manager) error {
	err := ctrl.NewWebhookManagedBy(mgr, &dynakube.DynaKube{}).WithDefaulter(&dkDefaulter{apiReader: mgr.GetAPIReader()}).Complete()
	if err != nil {
		return err
	}

	// next defaulting webhook

	return err
}
